// ICSE 10 Mathematics ch07 Factorisation of Polynomials: Remainder and Factor Theorems — practice bank with
// independent re-solve checks. Keys and option values are typed as literals; each check recomputes them with
// poly.mjs (exact fractions): every remainder by evaluation AND by long division, every factorisation by
// expanding back, every unknown coefficient by exact elimination and substitution. Every typed working line in
// a solution or model answer is parsed and checked by work.mjs, and every typed polynomial with unknowns is
// checked against the template used to solve it.
import { Q, mk, r, plot } from './lib.mjs';
import { P, F, Fr, lin, factorise, candidates, evalLine, btex, zeroOf, factorOfZero, rationalZeros, solveUnknowns, disc } from './poly.mjs';
import { steps, xctx, kctx, xkctx, zctx, IDX, ARITH, texEquals } from './work.mjs';

const J = (lines) => lines.join('\n\n');
const W = (ctx, lines) => steps(ctx, lines);
const num = (x) => Fr.of(x).num();
const neg = (t) => (t.startsWith('-') ? `−${t.slice(1)}` : t);

/** Remainder of f on division by the linear divisor dv, by evaluation AND by long division (they must agree). */
export function rem(f, dv, name = 'f') {
  const z = zeroOf(dv);
  const value = f.at(z);
  const { q, r: rr } = f.divBy(dv);
  if (rr.deg > 0 || !rr.co(0).eq(value)) throw new Error(`remainder theorem check failed for ${f.tex()} by ${dv.tex()}`);
  return { z, value, q, ev: evalLine(f, z, name) };
}
export const isFactor = (f, dv) => rem(f, dv).value.isZero();
/** Typed polynomial with unknowns must equal the template used to solve for them. */
const tplLine = (names, tpl, tex, name = 'f') => W({ ...xkctx(names, tpl), fns: { [name]: (x, env) => tpl(env).at(x) } }, [`${name}(x) = ${tex}`]);

/**
 * Factorisation working for a cubic: trial values up to the first zero, the division identity and the
 * complete factorisation. trials: values to show (default: the candidate order up to the first zero).
 */
export function factorWork(f, { name = 'f', trials = null } = {}) {
  const fac = factorise(f);
  const cand = candidates(f);
  const list = (trials ?? cand.slice(0, cand.findIndex((c) => f.at(c).isZero()) + 1)).map(Fr.of);
  const z = list[list.length - 1];
  if (!f.at(z).isZero()) throw new Error('the last trial value must be a zero');
  const dv = factorOfZero(z);
  const { q } = f.divBy(dv);
  const qf = factorise(q);
  const full = `${btex(dv)}${q.deg >= 1 && qf.factors.length ? qf.tex : btex(q)}`;
  const trialLines = list.map((a) => evalLine(f, a, name).tex);
  const idLine = full === `${btex(dv)}${btex(q)}` ? `${f.tex()} = ${btex(dv)}${btex(q)}` : `${f.tex()} = ${btex(dv)}${btex(q)} = ${full}`;
  const qLine = qf.factors.length ? `${q.tex()} = ${qf.tex}` : null;
  const ctx = { ...xctx(f, { name, zeros: rationalZeros(f), refs: [f, q] }) };
  const lines = [...trialLines, idLine, ...(qLine ? [qLine] : [])];
  return { fac, z, dv, q, qf, full, trialLines, idLine, qLine, w: W(ctx, lines) };
}
/** Long-division working lines (ICSE layout written as steps): divide leading terms, multiply back, subtract. */
export function divLines(f, dv) {
  const { q, r: rr, steps: st } = f.divBy(dv);
  const lead = (p) => P(p.lead, ...Array(p.deg).fill(0)).tex();
  const lines = st.flatMap((s) => [
    `\\dfrac{${lead(s.dividend)}}{${lead(dv)}} = ${s.term.tex()}`,
    `${s.term.tex() === '1' ? '' : s.term.tex() === '-1' ? '-' : s.term.tex()}${btex(dv)} = ${s.prod.tex()}`,
    `(${s.dividend.tex()}) - (${s.prod.tex()}) = ${s.rem.tex()}`,
  ]);
  return { q, r: rr, st, w: W(IDX, lines) };
}

// =============================================================== MCQ
const f01 = P(2, -3, 4, -5), r01 = rem(f01, lin(1, -2));
Q('m01', mk.mcq({ stem: r`According to the remainder theorem, when a polynomial $f(x)$ is divided by $(x - a)$, the remainder is`, opts: ['$f(a)$', '$f(-a)$', '$a$', '$f(0)$'], key: 'a', sol: `Write $f(x) = (x - a)q(x) + r$ and put $x = a$: the first term becomes $0$, so $r = f(a)$. For example, $${f01.tex()}$ divided by $(x - 2)$ leaves $7$, which is $f(2)$; $f(-2) = ${f01.at(-2).tex()}$.`, d: 1, c: 'recall', t: [1] }), (C) => { C.assert(r01.value.eq(7) && f01.divBy(lin(1, -2)).r.co(0).eq(7), 'remainder 7 = f(2) by division'); C.assert(!f01.at(-2).eq(7) && !f01.at(0).eq(7), 'f(-2), f(0) differ'); W(xctx(f01), [`f(-2) = ${f01.at(-2).tex()}`]).verify(C); C.which(['f(a)', 'f(-a)', 'a', 'f(0)'].map((o) => ({ 'f(a)': num(f01.at(2)), 'f(-a)': num(f01.at(-2)), a: 2, 'f(0)': num(f01.at(0)) })[o]), num(r01.value)); });

const f02 = P(1, -5, 2, 9), r02 = rem(f02, lin(1, -1));
Q('m02', mk.mcq({ stem: r`What is the remainder when $x^3 - 5x^2 + 2x + 9$ is divided by $(x - 1)$?`, opts: ['$7$', '$1$', '$9$', '$-2$'], key: 'a', sol: `Put $x = 1$: $${r02.ev.tex}$. Option (b) is $f(-1)$, and (c) is only the constant term, $f(0)$.`, d: 1, c: 'understanding', t: [1], time: 45 }), (C) => { W(xctx(f02), [r02.ev.tex]).verify(C); C.assert(texEquals(r`x^3 - 5x^2 + 2x + 9`, f02), 'stem polynomial'); C.assert(f02.at(-1).eq(1) && f02.at(0).eq(9), 'distractors f(-1), f(0)'); C.which([7, 1, 9, -2], num(r02.value)); });

const f03 = P(3, 1, -4, 2), d03 = lin(3, 1);
Q('m03', mk.mcq({ stem: r`To find the remainder when $3x^3 + x^2 - 4x + 2$ is divided by $(3x + 1)$ using the remainder theorem, which value of $x$ should be substituted?`, opts: [r`$-\dfrac{1}{3}$`, r`$\dfrac{1}{3}$`, '$-1$', '$-3$'], key: 'a', sol: r`Substitute the value that makes the divisor zero: $3x + 1 = 0$ gives $x = -\dfrac{1}{3}$, so the remainder is $f\left(-\dfrac{1}{3}\right)$. Option (b) has the wrong sign; (d) inverts the fraction.`, d: 2, c: 'understanding', t: [1] }), (C) => { W(zctx(F(-1, 3)), [r`3x + 1 = 0`, r`x = -\dfrac{1}{3}`]).verify(C); rem(f03, d03); C.which([-1 / 3, 1 / 3, -1, -3], num(zeroOf(d03))); });

const f04 = P(2, -3, 5, -4), r04 = rem(f04, lin(2, -1));
Q('m04', mk.mcq({ stem: r`Find the remainder when $2x^3 - 3x^2 + 5x - 4$ is divided by $(2x - 1)$.`, opts: ['$-2$', r`$-\dfrac{15}{2}$`, '$0$', '$10$'], key: 'a', sol: `$2x - 1 = 0$ gives $x = \\dfrac{1}{2}$, and $${r04.ev.tex}$. Option (b) substitutes $x = -\\dfrac{1}{2}$, (c) substitutes $x = 1$ and (d) substitutes $x = 2$.`, d: 2, c: 'understanding', t: [1], time: 75 }), (C) => { W(xctx(f04), [r04.ev.tex]).verify(C); C.assert(f04.at(F(-1, 2)).eq(F(-15, 2)) && f04.at(1).eq(0) && f04.at(2).eq(10), 'distractors'); C.which([-2, -7.5, 0, 10], num(r04.value)); });

const t05 = (e) => P(1, e.k, -2, 1);
const k05 = solveUnknowns(['k'], t05, [{ at: -2, value: 5 }]);
const w05 = W(kctx(['k'], t05, k05), [r`f(-2) = (-2)^3 + k \times (-2)^2 - 2 \times (-2) + 1 = -8 + 4k + 4 + 1 = 4k - 3`, r`4k - 3 = 5`, r`k = 2`]);
Q('m05', mk.mcq({ stem: r`When $x^3 + kx^2 - 2x + 1$ is divided by $(x + 2)$, the remainder is $5$. What is the value of $k$?`, opts: ['$2$', '$0$', r`$-\dfrac{1}{2}$`, r`$\dfrac{1}{2}$`], key: 'a', sol: `${w05.md[0]}, so ${w05.md[1]} and ${w05.md[2]}. Option (b) comes from substituting $x = 2$ instead of $x = -2$.`, d: 2, c: 'application', t: [1], time: 75 }), (C) => { w05.verify(C); tplLine(['k'], t05, r`x^3 + kx^2 - 2x + 1`).verify(C); C.assert(solveUnknowns(['k'], t05, [{ at: 2, value: 5 }]).k.eq(0) && solveUnknowns(['k'], t05, [{ at: -2, value: -5 }]).k.eq(F(-1, 2)), 'distractors'); C.which([2, 0, -0.5, 0.5], num(k05.k)); });

const f06 = P(1, -3, -6, 8);
const o06 = [lin(1, -1), lin(1, 1), lin(1, -2), lin(1, 4)];
Q('m06', mk.mcq({ stem: r`Which of the following is a factor of $x^3 - 3x^2 - 6x + 8$?`, opts: o06.map((d) => `$${btex(d)}$`), key: 'a', sol: `The coefficients add up to $1 - 3 - 6 + 8 = 0$, so $f(1) = 0$ and $(x - 1)$ is a factor. The others fail: $f(-1) = ${f06.at(-1).tex()}$, $f(2) = ${f06.at(2).tex()}$ and $f(-4) = ${f06.at(-4).tex()}$.`, d: 1, c: 'understanding', t: [2], time: 60 }), (C) => { W(ARITH, [r`1 - 3 - 6 + 8 = 0`]).verify(C); W(xctx(f06), [`f(1) = 0`, `f(-1) = ${f06.at(-1).tex()}`, `f(2) = ${f06.at(2).tex()}`, `f(-4) = ${f06.at(-4).tex()}`]).verify(C); C.which(o06.map((d) => (isFactor(f06, d) ? 'factor' : 'no')), 'factor'); });

const t07 = (e) => P(2, -5, e.k, -6);
const k07 = solveUnknowns(['k'], t07, [{ at: 3, value: 0 }]);
const w07 = W(kctx(['k'], t07, k07), [r`f(3) = 2 \times 3^3 - 5 \times 3^2 + 3k - 6 = 54 - 45 + 3k - 6 = 3k + 3`, r`3k + 3 = 0`, r`k = -1`]);
Q('m07', mk.mcq({ stem: r`If $(x - 3)$ is a factor of $2x^3 - 5x^2 + kx - 6$, then $k$ equals`, opts: ['$-1$', '$1$', '$-35$', '$-3$'], key: 'a', sol: `By the factor theorem $f(3) = 0$: ${w07.md[0]}, so ${w07.md[2]}. Option (c) comes from using $f(-3) = 0$ by mistake.`, d: 2, c: 'application', t: [2], time: 75 }), (C) => { w07.verify(C); tplLine(['k'], t07, r`2x^3 - 5x^2 + kx - 6`).verify(C); C.assert(solveUnknowns(['k'], t07, [{ at: -3, value: 0 }]).k.eq(-35), 'distractor -35'); C.which([-1, 1, -35, -3], num(k07.k)); });

const g08 = P(2, 1, 2, 1);
Q('m08', mk.mcq({ stem: r`$(2x + 1)$ is a factor of a polynomial $f(x)$. Which of these statements must be true?`, opts: [r`$f\left(-\dfrac{1}{2}\right) = 0$`, r`$f\left(\dfrac{1}{2}\right) = 0$`, '$f(-1) = 0$', '$f(2) = 0$'], key: 'a', sol: r`By the factor theorem, $(2x + 1)$ is a factor exactly when $f$ is zero at the value that makes $2x + 1 = 0$, that is $x = -\dfrac{1}{2}$. The others need not hold: for $f(x) = 2x^3 + x^2 + 2x + 1 = (2x + 1)(x^2 + 1)$, $f\left(\dfrac{1}{2}\right) = \dfrac{5}{2}$.`, d: 2, c: 'understanding', t: [2] }), (C) => { W(xctx(g08, { refs: [g08] }), [r`2x^3 + x^2 + 2x + 1 = (2x + 1)(x^2 + 1)`, r`f\left(\dfrac{1}{2}\right) = \dfrac{5}{2}`]).verify(C); C.which([F(-1, 2), F(1, 2), F(-1), F(2)].map((a) => (g08.at(a).isZero() ? 'zero' : 'no')), 'zero'); C.assert(zeroOf(lin(2, 1)).eq(F(-1, 2)), 'zero of 2x + 1'); });

const f09 = P(3, 2, -19, 6), fw09 = factorWork(f09, { trials: [2] });
const o09 = [r`(x - 2)(3x - 1)(x + 3)`, r`(x + 2)(3x + 1)(x - 3)`, r`(x - 2)(3x + 1)(x + 3)`, r`(x - 2)(x - 3)(3x + 1)`];
Q('m09', mk.mcq({ stem: r`Which of these is the complete factorisation of $3x^3 + 2x^2 - 19x + 6$?`, opts: o09.map((t) => `$${t}$`), key: 'a', sol: `$${fw09.trialLines[0]}$, so $(x - 2)$ is a factor. Dividing, $${fw09.idLine}$. Expanding (b) gives the signs of every term except $x^3$ reversed.`, d: 2, c: 'application', t: [3], time: 90 }), (C) => { fw09.w.verify(C); C.assert(fw09.full === r`(x - 2)(x + 3)(3x - 1)`, `full ${fw09.full}`); C.assert(texEquals(o09[1], P(3, -2, -19, -6)), '(b) reverses signs'); C.which(o09.map((t) => (texEquals(t, f09) ? 'yes' : 'no')), 'yes'); });

const f10 = P(1, 2, -13, 10), z10 = rationalZeros(f10);
const sets10 = [[1, -1, 2, -2, 5, -5, 10, -10], [1, -1, 13, -13], [1, -1, 2, -2], [0, 1]];
Q('m10', mk.mcq({ stem: r`You want to factorise $x^3 + 2x^2 - 13x + 10$ by trying values of $x$. Which values are worth trying first?`, opts: [r`the divisors of $10$: $\pm 1, \pm 2, \pm 5, \pm 10$`, r`the divisors of $13$: $\pm 1, \pm 13$`, r`the divisors of $2$: $\pm 1, \pm 2$`, r`only $x = 0$ and $x = 1$`], key: 'a', sol: `An integer zero of a polynomial with leading coefficient $1$ must divide the constant term, $10$. Trying them, $${evalLine(f10, 1).tex}$, so $(x - 1)$ is a factor; in fact $${f10.tex()} = ${factorise(f10).tex}$.`, d: 2, c: 'understanding', t: [3] }), (C) => { W(xctx(f10, { zeros: z10, refs: [f10] }), [evalLine(f10, 1).tex, `${f10.tex()} = ${factorise(f10).tex}`]).verify(C); C.assert(z10.map(String).join() === '-5,1,2', 'zeros -5, 1, 2'); C.which(sets10.map((s) => (z10.every((z) => s.includes(num(z))) ? 'all' : 'misses')), 'all'); });

const f11 = P(3, -5, 4, -2);
const o11 = [lin(1, -1), lin(1, 1), lin(3, -2), lin(1, -2)];
Q('m11', mk.mcq({ stem: r`The coefficients of $3x^3 - 5x^2 + 4x - 2$ add up to $0$. Which factor does this show the polynomial has?`, opts: o11.map((d) => `$${btex(d)}$`), key: 'a', sol: `The sum of the coefficients is $f(1)$: $3 - 5 + 4 - 2 = 0$, so $(x - 1)$ is a factor. The others are not: $f(-1) = ${f11.at(-1).tex()}$, $f\\left(\\dfrac{2}{3}\\right) = ${f11.at(F(2, 3)).tex()}$ and $f(2) = ${f11.at(2).tex()}$.`, d: 2, c: 'understanding', t: [2], time: 60 }), (C) => { W(ARITH, [r`3 - 5 + 4 - 2 = 0`]).verify(C); W(xctx(f11), [`f(1) = 0`, `f(-1) = ${f11.at(-1).tex()}`, r`f\left(\dfrac{2}{3}\right) = ${f11.at(F(2, 3)).tex()}`]).verify(C); C.which(o11.map((d) => (isFactor(f11, d) ? 'factor' : 'no')), 'factor'); });

const t12 = (e) => P(1, 0, e.a, 4);
const a12 = solveUnknowns(['a'], t12, [{ g: (e) => t12(e).at(1).sub(t12(e).at(-1)) }]);
const w12 = W(kctx(['a'], t12, a12), [r`f(1) = 1 + a + 4 = a + 5`, r`f(-1) = -1 - a + 4 = 3 - a`, r`a + 5 = 3 - a`, r`2a = -2`, r`a = -1`]);
Q('m12', mk.mcq({ stem: r`The polynomial $x^3 + ax + 4$ leaves the same remainder when divided by $(x - 1)$ as when divided by $(x + 1)$. Find $a$.`, opts: ['$-1$', '$1$', '$-4$', '$4$'], key: 'a', sol: `${w12.md[0]} and ${w12.md[1]}. Equal remainders: ${w12.md[2]}, so ${w12.md[3]} and ${w12.md[4]}.`, d: 3, c: 'analysis', t: [1], time: 90 }), (C) => { w12.verify(C); tplLine(['a'], t12, r`x^3 + ax + 4`).verify(C); C.which([-1, 1, -4, 4].map((a) => { const g = t12({ a: F(a) }); return g.at(1).eq(g.at(-1)) ? 'equal' : 'no'; }), 'equal'); C.assert(a12.a.eq(-1), 'a = -1'); });

const t13 = (e) => P(1, e.p, e.q, 2);
const pq13 = solveUnknowns(['p', 'q'], t13, [{ at: 1, value: 0 }, { at: -2, value: 0 }]);
const w13 = W(kctx(['p', 'q'], t13, pq13), [r`f(1) = 1 + p + q + 2 = 0 \Rightarrow p + q = -3`, r`f(-2) = -8 + 4p - 2q + 2 = 0 \Rightarrow 2p - q = 3`, r`3p = 0`, r`p = 0`, r`q = -3`]);
const o13 = [[0, -3], [-3, 0], [0, 3], [1, -4]];
Q('m13', mk.mcq({ stem: r`Both $(x - 1)$ and $(x + 2)$ are factors of $x^3 + px^2 + qx + 2$. What are $p$ and $q$?`, opts: o13.map(([p, q]) => `$p = ${p},\\ q = ${q}$`), key: 'a', sol: `${w13.md[0]} and ${w13.md[1]}. Adding, ${w13.md[2]}, so ${w13.md[3]} and ${w13.md[4]}. Option (d) makes $f(1) = 0$ but gives $f(-2) = ${t13({ p: F(1), q: F(-4) }).at(-2).tex()}$.`, d: 3, c: 'application', t: [2], time: 120 }), (C) => { w13.verify(C); tplLine(['p', 'q'], t13, r`x^3 + px^2 + qx + 2`).verify(C); C.which(o13.map(([p, q]) => { const g = t13({ p: F(p), q: F(q) }); return g.at(1).isZero() && g.at(-2).isZero() ? 'both' : 'no'; }), 'both'); C.assert(t13({ p: F(1), q: F(-4) }).at(1).isZero(), '(d) satisfies f(1) = 0'); });

const f14 = P(1, 0, -13, -12), q14 = f14.divBy(lin(1, 1)).q;
const o14 = [r`(x - 4)(x + 3)`, r`(x + 4)(x - 3)`, r`(x - 6)(x + 2)`, r`(x - 12)(x + 1)`];
const w14 = W(xctx(f14, { zeros: rationalZeros(f14), refs: [f14, q14] }), [`${f14.tex()} = (x + 1)(${q14.tex()})`, `${q14.tex()} = (x - 4)(x + 3)`]);
Q('m14', mk.mcq({ stem: r`One factor of $x^3 - 13x - 12$ is $(x + 1)$. What are the other two factors?`, opts: o14.map((t) => `$${t}$`), key: 'a', sol: `Dividing by $(x + 1)$: ${w14.md[0]}, and ${w14.md[1]}. Option (b) has both signs reversed.`, d: 2, c: 'understanding', t: [3], time: 75 }), (C) => { w14.verify(C); C.assert(isFactor(f14, lin(1, 1)), '(x + 1) is a factor'); C.which(o14.map((t) => (texEquals(`(x + 1)${t}`, f14) ? 'yes' : 'no')), 'yes'); });

const f15 = lin(1, -2).mul(P(1, 3, -1)).add(P(4));
Q('m15', mk.mcq({ stem: r`When a polynomial $f(x)$ is divided by $(x - 2)$, the quotient is $x^2 + 3x - 1$ and the remainder is $4$. What is $f(2)$?`, opts: ['$4$', '$9$', '$0$', '$13$'], key: 'a', sol: r`$f(x) = (x - 2)(x^2 + 3x - 1) + 4$. At $x = 2$ the first term is $0$: $f(2) = 0 \times 9 + 4 = 4$. This is the remainder theorem. Option (b) is the value of the quotient at $x = 2$.`, d: 2, c: 'understanding', t: [1] }), (C) => { W(xctx(f15), [r`f(2) = 0 \times 9 + 4 = 4`]).verify(C); C.assert(P(1, 3, -1).at(2).eq(9) && rem(f15, lin(1, -2)).value.eq(4), 'f(2) = 4, q(2) = 9'); C.which([4, 9, 0, 13], num(f15.at(2))); });

const o16 = [P(1, 2, 3, 2), P(1, 2, -3, 2), P(1, -2, 3, 2), P(1, 1, 1, 2)];
Q('m16', mk.mcq({ stem: r`Which of these polynomials is exactly divisible by $(x + 1)$?`, opts: o16.map((p) => `$${p.tex()}$`), key: 'a', sol: `Put $x = -1$ in each. For the first, $${evalLine(o16[0], -1).tex}$. The others give $${o16[1].at(-1).tex()}$, $${o16[2].at(-1).tex()}$ and $${o16[3].at(-1).tex()}$, so they leave remainders.`, d: 2, c: 'understanding', t: [2], time: 75 }), (C) => { W(xctx(o16[0]), [evalLine(o16[0], -1).tex]).verify(C); C.which(o16.map((p) => (isFactor(p, lin(1, 1)) ? 'divisible' : 'no')), 'divisible'); });

const f17 = P(1, -6, 5, 12), z17 = rationalZeros(f17);
const fig17 = plot({ x: [-2, 5], y: [-32, 16], fns: [{ expr: f17.tex() }], pts: z17.map((z) => [num(z), 0, `(${neg(z.tex())}, 0)`]) }, 'Graph of a cubic polynomial y equals f of x, rising from the bottom left, crossing the x-axis at the three marked points minus 1, 3 and 4, with a turning point above the axis between minus 1 and 3.', 'The cubic crosses the $x$-axis only at the marked points.');
const o17 = [lin(1, 3), lin(1, 1), lin(1, -3), lin(1, -4)];
Q('m17', mk.mcq({ stem: r`The graph of a cubic polynomial $y = f(x)$ crosses the $x$-axis only at the three marked points. Which of these is **not** a factor of $f(x)$?`, opts: o17.map((d) => `$${btex(d)}$`), key: 'a', sol: r`The graph meets the $x$-axis where $f(x) = 0$: at $x = -1$, $3$ and $4$. So $(x + 1)$, $(x - 3)$ and $(x - 4)$ are factors. $(x + 3)$ would need $f(-3) = 0$, but the graph does not cross the axis at $-3$.`, d: 3, c: 'analysis', t: [2], time: 75, assets: [fig17] }), (C) => { C.assert(z17.map(String).join() === '-1,3,4' && factorise(f17).factors.length === 3, 'zeros -1, 3, 4'); W(xctx(f17, { zeros: z17 }), [r`f(-1) = 0`, r`f(3) = 0`, r`f(4) = 0`, `f(-3) = ${f17.at(-3).tex()}`]).verify(C); C.which(o17.map((d) => (isFactor(f17, d) ? 'factor' : 'not')), 'not'); });

const f18 = P(1, -6, 3, 10), fw18 = factorWork(f18, { trials: [2] });
const wrong18 = P(1, -4, 5);
const w18 = W(IDX, [r`(x - 2)(x^2 - 4x + 5) = x^3 - 6x^2 + 13x - 10`]);
Q('m18', mk.mcq({ stem: r`Meera found that $(x - 2)$ is a factor of $x^3 - 6x^2 + 3x + 10$. She wrote $x^3 - 6x^2 + 3x + 10 = (x - 2)(x^2 - 4x + 5)$ and said that it cannot be factorised further. Which statement is correct?`, opts: [r`Her quotient is wrong: it should be $x^2 - 4x - 5$, which factorises as $(x - 5)(x + 1)$.`, r`Her work is correct, because $x^2 - 4x + 5$ has no linear factors.`, r`$(x - 2)$ is not a factor, because $f(2) \ne 0$.`, r`Her quotient should be $x^2 + 4x - 5$.`], key: 'a', sol: `Expanding her product: ${w18.md[0]}, which is not the given polynomial. The correct division gives $${fw18.idLine}$.`, d: 3, c: 'analysis', t: [3], time: 90 }), (C) => { w18.verify(C); fw18.w.verify(C); C.assert(fw18.q.tex() === 'x^2 - 4x - 5' && !lin(1, -2).mul(wrong18).eq(f18), 'her quotient is wrong'); const truth = [fw18.q.eq(P(1, -4, -5)) && fw18.qf.factors.length === 2, lin(1, -2).mul(wrong18).eq(f18), !isFactor(f18, lin(1, -2)), lin(1, -2).mul(P(1, 4, -5)).eq(f18)]; C.which(truth.map((t) => (t ? 'true' : 'false')), 'true'); });

// =============================================================== assertion-reason (keys a b d c a d)
const far1 = P(1, 2, -1, 3), rar1 = rem(far1, lin(1, 2));
Q('ar1', mk.ar({ a: r`The remainder when $x^3 + 2x^2 - x + 3$ is divided by $(x + 2)$ is $5$.`, r: r`When a polynomial $f(x)$ is divided by $(x + a)$, the remainder is $f(-a)$.`, key: 'a', sol: `$${rar1.ev.tex}$, so A is true. R is the remainder theorem for the divisor $x + a$, whose zero is $-a$, and it is exactly the rule used to get A.`, d: 2, c: 'understanding', t: [1] }), (C) => { W(xctx(far1), [rar1.ev.tex]).verify(C); C.assert(rar1.value.eq(5), 'remainder 5'); C.key('a'); });
const far2 = P(1, 1, -4, -4);
Q('ar2', mk.ar({ a: r`$(x - 2)$ is a factor of $x^3 + x^2 - 4x - 4$.`, r: r`The constant term of $x^3 + x^2 - 4x - 4$ is divisible by $2$.`, key: 'b', sol: `$${evalLine(far2, 2).tex}$, so A is true by the factor theorem. R is also true, but divisibility of the constant term only makes $2$ a value worth trying: $4$ also divides $-4$, yet $f(4) = ${far2.at(4).tex()}$. So R does not explain A.`, d: 3, c: 'analysis', t: [2] }), (C) => { W(xctx(far2), [evalLine(far2, 2).tex, `f(4) = ${far2.at(4).tex()}`]).verify(C); C.assert(isFactor(far2, lin(1, -2)) && !isFactor(far2, lin(1, -4)), 'A true; 4 is not a zero'); C.key('b'); });
const far3 = P(1, -2, 3, -6), fac3 = factorise(far3);
Q('ar3', mk.ar({ a: r`$x^3 - 2x^2 + 3x - 6$ can be written as a product of three linear factors with integer coefficients.`, r: r`$x^2 + 3$ is positive for every real value of $x$.`, key: 'd', sol: r`Grouping, $x^3 - 2x^2 + 3x - 6 = x^2(x - 2) + 3(x - 2) = (x - 2)(x^2 + 3)$. Since $x^2 + 3 \ge 3$, it is never zero and has no linear factor, so A is false. R is true.`, d: 3, c: 'analysis', t: [3] }), (C) => { W(xctx(far3, { zeros: [2], refs: [far3] }), [r`x^3 - 2x^2 + 3x - 6 = x^2(x - 2) + 3(x - 2) = (x - 2)(x^2 + 3)`]).verify(C); C.assert(fac3.factors.length === 1 && fac3.rest.deg === 2 && disc(fac3.rest).sign() < 0, 'one linear factor only'); C.key('d'); });
const far4 = P(8, 0, -4, 3), rar4 = rem(far4, lin(2, 1));
Q('ar4', mk.ar({ a: r`The remainder when $8x^3 - 4x + 3$ is divided by $(2x + 1)$ is $4$.`, r: r`The remainder when $f(x)$ is divided by $(ax + b)$ is $f\left(\dfrac{b}{a}\right)$.`, key: 'c', sol: `$${rar4.ev.tex}$, so A is true. R is false: the value to substitute is the zero of $ax + b$, which is $-\\dfrac{b}{a}$. Here R would give $f\\left(\\dfrac{1}{2}\\right) = ${far4.at(F(1, 2)).tex()}$, not $4$.`, d: 2, c: 'understanding', t: [1] }), (C) => { W(xctx(far4), [rar4.ev.tex, r`f\left(\dfrac{1}{2}\right) = ${far4.at(F(1, 2)).tex()}`]).verify(C); C.assert(rar4.value.eq(4) && !far4.at(F(1, 2)).eq(4), 'A true, R false'); C.key('c'); });
const tar5 = (e) => P(1, e.k, 1, 6);
const kar5 = solveUnknowns(['k'], tar5, [{ at: -1, value: 0 }]);
const war5 = W(kctx(['k'], tar5, kar5), [r`f(-1) = -1 + k - 1 + 6 = k + 4`, r`k + 4 = 0`, r`k = -4`]);
Q('ar5', mk.ar({ a: r`If $(x + 1)$ is a factor of $x^3 + kx^2 + x + 6$, then $k = -4$.`, r: r`$(x + 1)$ is a factor of a polynomial $f(x)$ exactly when $f(-1) = 0$.`, key: 'a', sol: `${war5.md[0]}; setting ${war5.md[1]} gives ${war5.md[2]}. R is the factor theorem, and it is the reason A holds.`, d: 2, c: 'application', t: [2] }), (C) => { war5.verify(C); tplLine(['k'], tar5, r`x^3 + kx^2 + x + 6`).verify(C); C.assert(kar5.k.eq(-4), 'k = -4'); C.key('a'); });
const far6 = P(1, -6, 9, -3), rar6 = rem(far6, lin(1, -3));
Q('ar6', mk.ar({ a: r`Dividing $x^3 - 6x^2 + 9x - 3$ by $(x - 3)$ leaves $3$ over.`, r: r`Substituting $x = a$ in a polynomial $f(x)$ gives the remainder on division by $(x - a)$.`, key: 'd', sol: `$${rar6.ev.tex}$, so the remainder is $-3$, not $3$: A is false. R is the remainder theorem, which is true.`, d: 2, c: 'understanding', t: [1] }), (C) => { W(xctx(far6), [rar6.ev.tex]).verify(C); C.assert(rar6.value.eq(-3), 'remainder -3'); C.key('d'); });

// =============================================================== true-false
const ftf1 = P(2, -5, 1, 2);
Q('tf1', mk.tf({ stem: r`If the coefficients of a polynomial $f(x)$ add up to $0$, then $(x - 1)$ is a factor of $f(x)$.`, key: 't', sol: r`Putting $x = 1$ in $f(x)$ just adds the coefficients, so $f(1) = 0$ and the factor theorem gives the factor $(x - 1)$. For example, in $2x^3 - 5x^2 + x + 2$: $2 - 5 + 1 + 2 = 0$.`, d: 1, c: 'understanding', t: [2] }), (C) => { W(ARITH, [r`2 - 5 + 1 + 2 = 0`]).verify(C); C.assert(isFactor(ftf1, lin(1, -1)) && [P(3, -1, -4, 2), P(1, 0, -7, 6)].every((p) => p.at(1).eq(p.c.reduce((s, a) => s.add(a), F(0)))), 'f(1) = sum of coefficients'); C.key('t'); });
const ftf2 = P(1, 0, 5, -2);
Q('tf2', mk.tf({ stem: r`When a cubic polynomial is divided by $(x - 4)$, the remainder can be an expression of degree $1$, such as $2x + 3$.`, key: 'f', sol: r`The remainder always has a smaller degree than the divisor. $(x - 4)$ has degree $1$, so the remainder is a constant (possibly $0$).`, d: 2, c: 'understanding', t: [1] }), (C) => { C.assert([ftf2, P(2, -1, 0, 7), P(-3, 4, 1, 1)].every((p) => p.divBy(lin(1, -4)).r.deg <= 0), 'remainders are constants'); C.key('f'); });
const ftf3 = P(1, 0, -2, 7), rtf3 = rem(ftf3, lin(1, 3));
Q('tf3', mk.tf({ stem: r`When $x^3 - 2x + 7$ is divided by $(x + 3)$, the remainder is $-14$.`, key: 't', sol: `$x + 3 = 0$ gives $x = -3$, and $${rtf3.ev.tex}$.`, d: 2, c: 'understanding', t: [1] }), (C) => { W(xctx(ftf3), [rtf3.ev.tex]).verify(C); C.assert(rtf3.value.eq(-14), 'remainder -14'); C.key('t'); });
const ftf4 = P(1, 0, 0, 8);
Q('tf4', mk.tf({ stem: r`$(x + 2)$ is a factor of $x^3 + 8$.`, key: 't', sol: `$${evalLine(ftf4, -2).tex}$, so $(x + 2)$ is a factor; indeed $x^3 + 8 = (x + 2)(x^2 - 2x + 4)$.`, d: 1, c: 'understanding', t: [2] }), (C) => { W(xctx(ftf4, { zeros: [-2], refs: [ftf4] }), [evalLine(ftf4, -2).tex, r`x^3 + 8 = (x + 2)(x^2 - 2x + 4)`]).verify(C); C.assert(isFactor(ftf4, lin(1, 2)), 'factor'); C.key('t'); });
const ftf5 = P(1, -1, -5, -3), qtf5 = ftf5.divBy(lin(1, 1)).q;
Q('tf5', mk.tf({ stem: r`The cubic polynomial $x^3 - x^2 - 5x - 3$ has three different linear factors.`, key: 'f', sol: `$${evalLine(ftf5, -1).tex}$. Dividing by $(x + 1)$ gives $${qtf5.tex()} = (x + 1)(x - 3)$, so $x^3 - x^2 - 5x - 3 = (x + 1)^2(x - 3)$: the factor $(x + 1)$ is repeated, and there are only two different linear factors.`, d: 3, c: 'analysis', t: [3] }), (C) => { W(xctx(ftf5, { zeros: [-1, 3], refs: [ftf5, qtf5] }), [evalLine(ftf5, -1).tex, `${qtf5.tex()} = (x + 1)(x - 3)`, r`x^3 - x^2 - 5x - 3 = (x + 1)^2(x - 3)`]).verify(C); C.assert(rationalZeros(ftf5).length === 2 && factorise(ftf5).factors.length === 3, 'repeated factor'); C.key('f'); });
const ftf6 = P(1, 0, 0, -8);
Q('tf6', mk.tf({ stem: r`If $f(2) = 0$, then $(x + 2)$ is a factor of $f(x)$.`, key: 'f', sol: r`$f(2) = 0$ makes $(x - 2)$ a factor, not $(x + 2)$. For example, $f(x) = x^3 - 8$ has $f(2) = 0$ but $f(-2) = -16$.`, d: 1, c: 'understanding', t: [2] }), (C) => { W(xctx(ftf6), [r`f(2) = 0`, r`f(-2) = -16`]).verify(C); C.assert(isFactor(ftf6, lin(1, -2)) && !isFactor(ftf6, lin(1, 2)), 'counterexample'); C.key('f'); });

// =============================================================== fill in the blank
Q('fb1', mk.fill({ stem: r`To find the remainder when $f(x)$ is divided by $(x + 5)$, you work out the value of $f(x)$ at $x =$ ___.`, acc: [['-5', '−5']], sol: r`The divisor is zero when $x + 5 = 0$, that is at $x = -5$, so the remainder is $f(-5)$.`, d: 1, c: 'recall', t: [1] }), (C) => { W(zctx(-5), [r`x + 5 = 0`, r`x = -5`]).verify(C); C.blank(num(zeroOf(lin(1, 5)))); });
const ffb2 = P(2, -1, 0, 3), rfb2 = rem(ffb2, lin(1, -2));
Q('fb2', mk.fill({ stem: r`The remainder when $2x^3 - x^2 + 3$ is divided by $(x - 2)$ is ___.`, acc: [['15']], sol: `$${rfb2.ev.tex}$.`, d: 1, c: 'understanding', t: [1] }), (C) => { W(xctx(ffb2), [rfb2.ev.tex]).verify(C); C.blank(num(rfb2.value)); });
const tfb3 = (e) => P(1, -5, e.k, 8);
const kfb3 = solveUnknowns(['k'], tfb3, [{ at: 4, value: 0 }]);
const wfb3 = W(kctx(['k'], tfb3, kfb3), [r`f(4) = 4^3 - 5 \times 4^2 + 4k + 8 = 64 - 80 + 4k + 8 = 4k - 8`, r`4k - 8 = 0`, r`k = 2`]);
Q('fb3', mk.fill({ stem: r`If $(x - 4)$ is a factor of $x^3 - 5x^2 + kx + 8$, then $k =$ ___.`, acc: [['2']], sol: `${wfb3.md[0]}. By the factor theorem ${wfb3.md[1]}, so ${wfb3.md[2]}.`, d: 2, c: 'application', t: [2] }), (C) => { wfb3.verify(C); tplLine(['k'], tfb3, r`x^3 - 5x^2 + kx + 8`).verify(C); C.blank(num(kfb3.k)); });
const ffb4 = P(1, -2, -9, 18);
Q('fb4', mk.fill({ stem: r`When $x^3 - 2x^2 - 9x + 18$ is factorised completely, two of its factors are $(x - 2)$ and $(x - 3)$. The third factor is ___.`, acc: [['(x + 3)', 'x + 3', 'x+3', '(x+3)']], sol: r`Grouping: $x^3 - 2x^2 - 9x + 18 = x^2(x - 2) - 9(x - 2) = (x - 2)(x^2 - 9) = (x - 2)(x - 3)(x + 3)$. So the third factor is (x + 3).`, d: 2, c: 'application', t: [3] }), (C) => { W(xctx(ffb4, { zeros: [-3, 2, 3], refs: [ffb4] }), [r`x^3 - 2x^2 - 9x + 18 = x^2(x - 2) - 9(x - 2) = (x - 2)(x^2 - 9) = (x - 2)(x - 3)(x + 3)`]).verify(C); C.assert(factorise(ffb4).tex === '(x + 3)(x - 2)(x - 3)', 'factorisation'); C.blank('(x + 3)'); });
const ffb5 = P(6, 1, 0, -4), rfb5 = rem(ffb5, lin(2, -1));
Q('fb5', mk.fill({ stem: r`Use the remainder theorem with the divisor $(2x - 1)$: for the polynomial $6x^3 + x^2 - 4$, the remainder is ___.`, acc: [['-3', '−3']], sol: `$2x - 1 = 0$ gives $x = \\dfrac{1}{2}$: $${rfb5.ev.tex}$.`, d: 2, c: 'understanding', t: [1] }), (C) => { W(xctx(ffb5), [rfb5.ev.tex]).verify(C); C.blank(num(rfb5.value)); });
Q('fb6', mk.fill({ stem: r`By the factor theorem, if $f(-2) = 0$, then ___ is a factor of $f(x)$.`, acc: [['(x + 2)', 'x + 2', 'x+2', '(x+2)']], sol: r`$x = -2$ is the zero of $x + 2$, so (x + 2) is a factor.`, d: 1, c: 'recall', t: [2] }), (C) => { C.assert(factorOfZero(-2).tex() === 'x + 2', 'factor of zero -2'); C.blank('(x + 2)'); });

// =============================================================== numerical
const fn01 = P(1, -4, 6, -5), rn01 = rem(fn01, lin(1, -3));
Q('n01', mk.num({ stem: r`Without long division, calculate what is left over when $(x - 3)$ divides $x^3 - 4x^2 + 6x - 5$.`, value: 4, sol: `Put $x = 3$: $${rn01.ev.tex}$. The remainder is $4$.`, scheme: [['4', 1]], d: 1, c: 'understanding', t: [1], time: 60 }), (C) => { W(xctx(fn01), [rn01.ev.tex]).verify(C); C.val(num(rn01.value)); });
const fn02 = P(4, 2, -1, 7), rn02 = rem(fn02, lin(2, 1));
Q('n02', mk.num({ stem: r`Find the remainder when $4x^3 + 2x^2 - x + 7$ is divided by $(2x + 1)$. Give your answer as a decimal.`, value: 7.5, sol: `$2x + 1 = 0$ gives $x = -\\dfrac{1}{2}$, and $${rn02.ev.tex}$. So the remainder is $\\dfrac{15}{2} = 7.5$.`, scheme: [['7.5', 1]], d: 2, c: 'application', t: [1], time: 75 }), (C) => { W(xctx(fn02), [rn02.ev.tex, r`\dfrac{15}{2} = 7.5`]).verify(C); C.val(num(rn02.value)); });
const tn03 = (e) => P(3, e.k.neg(), 5, -6);
const kn03 = solveUnknowns(['k'], tn03, [{ at: 2, value: 0 }]);
const wn03 = W(kctx(['k'], tn03, kn03), [r`f(2) = 3 \times 2^3 - k \times 2^2 + 5 \times 2 - 6 = 24 - 4k + 10 - 6 = 28 - 4k`, r`28 - 4k = 0`, r`k = 7`]);
Q('n03', mk.num({ marks: 2, stem: r`$(x - 2)$ is a factor of $3x^3 - kx^2 + 5x - 6$. Find the value of $k$.`, value: 7, sol: `By the factor theorem $f(2) = 0$. ${wn03.md[0]}, so ${wn03.md[1]} and ${wn03.md[2]}.`, scheme: [['f(2) = 28 − 4k', 1], ['k = 7', 1]], d: 2, c: 'application', t: [2], time: 90 }), (C) => { wn03.verify(C); tplLine(['k'], tn03, r`3x^3 - kx^2 + 5x - 6`).verify(C); C.val(num(kn03.k)); });
const tn04f = (e) => P(2, e.a, -3, 4), tn04g = (e) => P(1, -2, e.a, 1);
const an04 = solveUnknowns(['a'], tn04f, [{ g: (e) => tn04f(e).at(2).sub(tn04g(e).at(2)) }]);
const wn04 = W(kctx(['a'], { f: tn04f, g: tn04g }, an04), [r`f(2) = 16 + 4a - 6 + 4 = 4a + 14`, r`g(2) = 8 - 8 + 2a + 1 = 2a + 1`, r`4a + 14 = 2a + 1`, r`2a = -13`, r`a = -6.5`]);
Q('n04', mk.num({ marks: 2, stem: r`On division by $(x - 2)$, the remainders of $2x^3 + ax^2 - 3x + 4$ and of $x^3 - 2x^2 + ax + 1$ turn out to be equal. What is $a$?`, value: -6.5, sol: `Call them $f(x)$ and $g(x)$. ${wn04.md[0]} and ${wn04.md[1]}. Equal remainders: ${wn04.md[2]}, so ${wn04.md[3]} and ${wn04.md[4]}.`, scheme: [['Both remainders in terms of a', 1], ['a = −6.5', 1]], d: 3, c: 'analysis', t: [1], time: 120 }), (C) => { wn04.verify(C); tplLine(['a'], tn04f, r`2x^3 + ax^2 - 3x + 4`).verify(C); tplLine(['a'], tn04g, r`x^3 - 2x^2 + ax + 1`, 'g').verify(C); C.val(num(an04.a)); });
const fn05 = P(1, 0, -19, 30), fwn05 = factorWork(fn05, { trials: [3] });
Q('n05', mk.num({ marks: 2, stem: r`$(x - 3)$ is a factor of $x^3 - 19x + 30$. Factorise the polynomial completely and give the smallest value of $x$ for which it equals zero.`, value: -5, sol: `$${fwn05.trialLines[0]}$. Dividing, $${fwn05.idLine}$. The zeros are $3$, $2$ and $-5$, so the smallest is $x = -5$.`, scheme: [['Complete factorisation', 1], ['x = −5', 1]], d: 2, c: 'application', t: [3], time: 120 }), (C) => { fwn05.w.verify(C); W(xctx(fn05, { zeros: rationalZeros(fn05) }), [r`x = -5`]).verify(C); C.val(Math.min(...rationalZeros(fn05).map(num))); });
const tn06 = (e) => P(1, e.p, e.q, -2);
const pqn06 = solveUnknowns(['p', 'q'], tn06, [{ at: 1, value: 4 }, { at: -1, value: -2 }]);
const wn06 = W(kctx(['p', 'q'], tn06, pqn06), [r`f(1) = 1 + p + q - 2 = 4 \Rightarrow p + q = 5`, r`f(-1) = -1 + p - q - 2 = -2 \Rightarrow p - q = 1`, r`2p = 6`, r`p = 3`, r`q = 2`]);
Q('n06', mk.num({ marks: 2, stem: r`The polynomial $x^3 + px^2 + qx - 2$ leaves a remainder of $4$ when divided by $(x - 1)$ and a remainder of $-2$ when divided by $(x + 1)$. Find $p$.`, value: 3, sol: `${wn06.md[0]} and ${wn06.md[1]}. Adding, ${wn06.md[2]}, so ${wn06.md[3]} (and ${wn06.md[4]}).`, scheme: [['Two equations p + q = 5, p − q = 1', 1], ['p = 3', 1]], d: 3, c: 'application', t: [1], time: 120 }), (C) => { wn06.verify(C); tplLine(['p', 'q'], tn06, r`x^3 + px^2 + qx - 2`).verify(C); C.val(num(pqn06.p)); });
const fn07 = P(1, -2, -1, 2), tr07 = [1, -1, 2, -2, 3];
Q('n07', mk.num({ stem: r`How many of the expressions $(x - 1)$, $(x + 1)$, $(x - 2)$, $(x + 2)$ and $(x - 3)$ are factors of $x^3 - 2x^2 - x + 2$?`, value: 3, sol: `${tr07.map((a) => `$f(${a}) = ${fn07.at(a).tex()}$`).join(', ')}. Only $1$, $-1$ and $2$ give $0$, so the number of factors is $3$: $(x - 1)$, $(x + 1)$ and $(x - 2)$. That is, $\\text{factors} = 3$.`, scheme: [['3', 1]], d: 2, c: 'application', t: [2], time: 90 }), (C) => { W(xctx(fn07), tr07.map((a) => `f(${a}) = ${fn07.at(a).tex()}`)).verify(C); C.val(tr07.filter((a) => isFactor(fn07, factorOfZero(a))).length); });

// =============================================================== short, 2 marks
const fs201 = P(2, 3, -7, 1), rs201 = rem(fs201, lin(1, 3));
Q('s201', mk.short({ marks: 2, stem: r`Use the remainder theorem to find the remainder when $2x^3 + 3x^2 - 7x + 1$ is divided by $(x + 3)$.`, model: J([`Let $f(x) = ${fs201.tex()}$; $x + 3 = 0$ gives $x = -3$.`, `$${rs201.ev.tex}$`, 'By the remainder theorem, the remainder is $-5$.']), sol: 'Substitute the zero of the divisor into the polynomial; the value is the remainder.', scheme: [['Substituting x = −3', 1], ['Remainder −5', 1]], d: 2, c: 'understanding', t: [1], time: 120 }), (C) => { W(xctx(fs201), [rs201.ev.tex]).verify(C); C.model([num(rs201.value)]); C.assert(rs201.value.eq(-5), 'remainder -5'); });
const fs202 = P(1, -3, -13, 15), rs202 = rem(fs202, lin(1, -5));
Q('s202', mk.short({ marks: 2, stem: r`Show that $(x - 5)$ is a factor of $x^3 - 3x^2 - 13x + 15$.`, model: J([`Let $f(x) = ${fs202.tex()}$. Then $${rs202.ev.tex}$.`, 'Since $f(5) = 0$, $(x - 5)$ is a factor of $f(x)$ by the factor theorem.']), sol: 'Evaluate the polynomial at the zero of the given expression and use the factor theorem.', scheme: [['f(5) worked out', 1], ['f(5) = 0, so a factor', 1]], d: 1, c: 'understanding', t: [2], time: 90 }), (C) => { W(xctx(fs202), [rs202.ev.tex]).verify(C); C.assert(rs202.value.isZero(), 'factor'); C.model([5, 0]); });
const ts203 = (e) => P(1, e.k.neg(), 2, 3);
const ks203 = solveUnknowns(['k'], ts203, [{ at: 2, value: 7 }]);
const ws203 = W(kctx(['k'], ts203, ks203), [r`f(2) = 2^3 - k \times 2^2 + 2 \times 2 + 3 = 8 - 4k + 4 + 3 = 15 - 4k`, r`15 - 4k = 7`, r`4k = 8`, r`k = 2`]);
Q('s203', mk.short({ marks: 2, stem: r`When $x^3 - kx^2 + 2x + 3$ is divided by $(x - 2)$, the remainder is $7$. Find $k$.`, model: J([r`Let $f(x) = x^3 - kx^2 + 2x + 3$. By the remainder theorem the remainder is $f(2)$.`, ws203.md[0], `${ws203.md[1]}, so ${ws203.md[2]} and ${ws203.md[3]}.`]), sol: 'Write the remainder in terms of k by substituting the zero of the divisor, then equate it to the given remainder.', scheme: [['f(2) = 15 − 4k', 1], ['k = 2', 1]], d: 2, c: 'application', t: [1], time: 120 }), (C) => { ws203.verify(C); tplLine(['k'], ts203, r`x^3 - kx^2 + 2x + 3`).verify(C); C.assert(ks203.k.eq(2), 'k = 2'); C.model([15, 7, 2]); });
const fs204 = P(2, -3, 4, -6), rs204 = rem(fs204, lin(2, -3));
Q('s204', mk.short({ marks: 2, stem: r`Is $(2x - 3)$ a factor of $2x^3 - 3x^2 + 4x - 6$? Justify your answer.`, model: J([`Let $f(x) = ${fs204.tex()}$; $2x - 3 = 0$ gives $x = \\dfrac{3}{2}$.`, `$${rs204.ev.tex}$`, r`So, by the factor theorem, $(2x - 3)$ **is** a factor. (Indeed $2x^3 - 3x^2 + 4x - 6 = (2x - 3)(x^2 + 2)$.)`]), sol: 'Substitute the zero of 2x − 3, that is three halves, and check whether the value is zero.', scheme: [['f(3/2) worked out', 1], ['Value 0, so a factor', 1]], d: 2, c: 'understanding', t: [2], time: 120 }), (C) => { W(xctx(fs204, { zeros: [F(3, 2)], refs: [fs204] }), [rs204.ev.tex, r`2x^3 - 3x^2 + 4x - 6 = (2x - 3)(x^2 + 2)`]).verify(C); C.assert(rs204.value.isZero(), 'factor'); C.model([1.5, 0]); });
const fs205 = P(1, 3, -6, -8), rs205a = rem(fs205, lin(1, 4)), rs205b = rem(fs205, lin(1, -1));
Q('s205', mk.short({ marks: 2, stem: r`Test whether $(x + 4)$ and $(x - 1)$ are factors of $x^3 + 3x^2 - 6x - 8$.`, model: J([`Let $f(x) = ${fs205.tex()}$.`, `$${rs205a.ev.tex}$, so $(x + 4)$ is a factor.`, `$${rs205b.ev.tex}$, which is not $0$, so $(x - 1)$ is not a factor.`]), sol: 'Use the factor theorem twice: evaluate at the zero of each expression.', scheme: [['f(−4) = 0: factor', 1], ['f(1) = −10: not a factor', 1]], d: 2, c: 'understanding', t: [2], time: 120 }), (C) => { W(xctx(fs205), [rs205a.ev.tex, rs205b.ev.tex]).verify(C); C.assert(rs205a.value.isZero() && rs205b.value.eq(-10), 'values'); C.model([0, 10]); });

// =============================================================== short, 3 marks
const ts301 = (e) => P(2, e.k, -4, 1);
const ks301 = solveUnknowns(['k'], ts301, [{ at: F(1, 2), value: F(1, 2) }]);
const ws301 = W(kctx(['k'], ts301, ks301), [r`f\left(\dfrac{1}{2}\right) = 2 \times \left(\dfrac{1}{2}\right)^3 + k \times \left(\dfrac{1}{2}\right)^2 - 4 \times \dfrac{1}{2} + 1 = \dfrac{1}{4} + \dfrac{k}{4} - 2 + 1 = \dfrac{k - 3}{4}`, r`\dfrac{k - 3}{4} = \dfrac{1}{2}`, r`k - 3 = 2`, r`k = 5`]);
Q('s301', mk.short({ marks: 3, stem: r`When $2x^3 + kx^2 - 4x + 1$ is divided by $(2x - 1)$, the remainder is $\dfrac{1}{2}$. Find the value of $k$.`, model: J([r`Let $f(x) = 2x^3 + kx^2 - 4x + 1$; $2x - 1 = 0$ gives $x = \dfrac{1}{2}$, so the remainder is $f\left(\dfrac{1}{2}\right)$.`, ws301.md[0], `${ws301.md[1]}, so ${ws301.md[2]} and ${ws301.md[3]}.`]), sol: 'Find the zero of the divisor, substitute it, simplify to an expression in k and equate it to the remainder given.', scheme: [['x = 1/2 from the divisor', 1], ['f(1/2) = (k − 3)/4', 1], ['k = 5', 1]], d: 3, c: 'application', t: [1], time: 180 }), (C) => { ws301.verify(C); tplLine(['k'], ts301, r`2x^3 + kx^2 - 4x + 1`).verify(C); C.assert(ks301.k.eq(5), 'k = 5'); C.model([5, r`\dfrac{k - 3}{4}`]); });
const ts302 = (e) => P(1, e.k, -4, 12);
const ks302 = solveUnknowns(['k'], ts302, [{ at: 3, value: 0 }]);
const fs302 = ts302(ks302);
const ws302 = W(kctx(['k'], ts302, ks302), [r`f(3) = 27 + 9k - 12 + 12 = 9k + 27`, r`9k + 27 = 0`, r`k = -3`]);
const xs302 = W(xctx(fs302, { zeros: rationalZeros(fs302), refs: [fs302] }), [r`x^3 - 3x^2 - 4x + 12 = x^2(x - 3) - 4(x - 3) = (x - 3)(x^2 - 4) = (x - 3)(x - 2)(x + 2)`]);
Q('s302', mk.short({ marks: 3, stem: r`$(x - 3)$ is a factor of $x^3 + kx^2 - 4x + 12$. Find $k$ and hence factorise the polynomial completely.`, model: J([r`Let $f(x) = x^3 + kx^2 - 4x + 12$. By the factor theorem, $f(3) = 0$:`, ws302.md[0], `${ws302.md[1]}, so ${ws302.md[2]}.`, 'Then, grouping:', xs302.md[0]]), sol: 'Use f(3) = 0 to find k; then factorise the cubic by grouping (or by dividing by x − 3) and factorise the quotient.', scheme: [['k = −3', 1], ['Quotient x² − 4', 1], ['(x − 3)(x − 2)(x + 2)', 1]], d: 3, c: 'application', t: [2, 3], time: 240 }), (C) => { ws302.verify(C); xs302.verify(C); tplLine(['k'], ts302, r`x^3 + kx^2 - 4x + 12`).verify(C); C.assert(fs302.tex() === 'x^3 - 3x^2 - 4x + 12' && factorise(fs302).factors.length === 3, 'k = -3, three factors'); C.model([3, r`(x - 3)(x - 2)(x + 2)`]); });
const fs303 = P(1, -4, -11, 30), fw303 = factorWork(fs303);
Q('s303', mk.short({ marks: 3, stem: r`Using the factor theorem, factorise completely: $x^3 - 4x^2 - 11x + 30$.`, model: J([`Let $f(x) = ${fs303.tex()}$. Try divisors of $30$:`, ...fw303.trialLines.map((l) => `$${l}$`), `So $${btex(fw303.dv)}$ is a factor. Dividing by it:`, `$${fw303.idLine}$`, `$${fw303.qLine}$`]), sol: 'Try divisors of the constant term until the polynomial is zero, divide by that factor and factorise the quadratic quotient.', scheme: [['A zero found by trial (x = 2)', 1], ['Quotient x² − 2x − 15', 1], ['Complete factorisation', 1]], d: 2, c: 'application', t: [3], time: 240 }), (C) => { fw303.w.verify(C); C.assert(fw303.z.eq(2) && fw303.full === '(x - 2)(x + 3)(x - 5)', `full ${fw303.full}`); C.model([16, 36, 0, fw303.full]); });
const fs304 = P(2, 1, -13, 6), fw304 = factorWork(fs304, { trials: [1, 2] });
Q('s304', mk.short({ marks: 3, stem: r`Factorise $2x^3 + x^2 - 13x + 6$ completely.`, model: J([`Let $f(x) = ${fs304.tex()}$.`, ...fw304.trialLines.map((l) => `$${l}$`), `So $${btex(fw304.dv)}$ is a factor, and`, `$${fw304.idLine}$`, `$${fw304.qLine}$`]), sol: 'Find one zero by trial, divide, then factorise the quadratic quotient by splitting the middle term.', scheme: [['A zero by trial (x = 2)', 1], ['Quotient 2x² + 5x − 3', 1], ['(x − 2)(2x − 1)(x + 3)', 1]], d: 2, c: 'application', t: [3], time: 240 }), (C) => { fw304.w.verify(C); C.assert(fw304.z.eq(2) && fw304.full === '(x - 2)(x + 3)(2x - 1)', `full ${fw304.full}`); C.model([0, fw304.full]); });
const ts305f = (e) => P(1, e.k, 0, -6), ts305g = (e) => P(2, e.k, 3);
const ks305 = solveUnknowns(['k'], ts305f, [{ g: (e) => ts305f(e).at(-1).sub(ts305g(e).at(-1)) }]);
const ws305 = W(kctx(['k'], { f: ts305f, g: ts305g }, ks305), [r`f(-1) = -1 + k - 6 = k - 7`, r`g(-1) = 2 - k + 3 = 5 - k`, r`k - 7 = 5 - k`, r`2k = 12`, r`k = 6`]);
Q('s305', mk.short({ marks: 3, stem: r`The polynomials $x^3 + kx^2 - 6$ and $2x^2 + kx + 3$ leave the same remainder when each is divided by $(x + 1)$. Find $k$.`, model: J([r`Let $f(x) = x^3 + kx^2 - 6$ and $g(x) = 2x^2 + kx + 3$.`, `${ws305.md[0]}; ${ws305.md[1]}.`, `${ws305.md[2]}, so ${ws305.md[3]} and ${ws305.md[4]}.`, r`Check: with $k = 6$ both remainders are $-1$.`]), sol: 'Find each remainder by substituting the zero of the divisor; equate the two remainders and solve for k.', scheme: [['f(−1) = k − 7', 1], ['g(−1) = 5 − k', 1], ['k = 6', 1]], d: 3, c: 'analysis', t: [1], time: 180 }), (C) => { ws305.verify(C); tplLine(['k'], ts305f, r`x^3 + kx^2 - 6`).verify(C); tplLine(['k'], ts305g, r`2x^2 + kx + 3`, 'g').verify(C); C.assert(ts305f(ks305).at(-1).eq(-1) && ts305g(ks305).at(-1).eq(-1), 'both remainders -1'); C.model([7, 5, 6, -1]); });
const fs306 = P(1, 5, 7, 3), qs306 = fs306.divBy(lin(1, 1)).q;
const ws306 = W(xctx(fs306, { zeros: [-3, -1], refs: [fs306, qs306] }), [evalLine(fs306, -1).tex, `${fs306.tex()} = (x + 1)(${qs306.tex()})`, `${qs306.tex()} = (x + 1)(x + 3)`, r`x^3 + 5x^2 + 7x + 3 = (x + 1)^2(x + 3)`]);
Q('s306', mk.short({ marks: 3, stem: r`Show that $(x + 1)$ is a factor of $x^3 + 5x^2 + 7x + 3$, and find the other factors.`, model: J([`Let $f(x) = ${fs306.tex()}$.`, `${ws306.md[0]}, so $(x + 1)$ is a factor.`, `Dividing: ${ws306.md[1]}.`, `${ws306.md[2]}.`, `So ${ws306.md[3]}: the factor $(x + 1)$ occurs twice.`]), sol: 'Show the value at x = −1 is zero, divide by x + 1 and factorise the quotient; notice the repeated factor.', scheme: [['f(−1) = 0', 1], ['Quotient x² + 4x + 3', 1], ['(x + 1)²(x + 3)', 1]], d: 3, c: 'application', t: [2, 3], time: 180 }), (C) => { ws306.verify(C); C.assert(rationalZeros(fs306).length === 2, 'repeated zero'); C.model([0, r`(x + 1)^2(x + 3)`]); });

// =============================================================== short, 4 marks
const ts401 = (e) => P(2, e.a, e.b, -2);
const ab401 = solveUnknowns(['a', 'b'], ts401, [{ at: -2, value: 0 }, { at: 1, value: 6 }]);
const ws401 = W(kctx(['a', 'b'], ts401, ab401), [r`f(-2) = -16 + 4a - 2b - 2 = 0 \Rightarrow 2a - b = 9`, r`f(1) = 2 + a + b - 2 = 6 \Rightarrow a + b = 6`, r`3a = 15`, r`a = 5`, r`b = 1`]);
Q('s401', mk.short({ marks: 4, stem: r`$(x + 2)$ is a factor of $2x^3 + ax^2 + bx - 2$, and the polynomial leaves a remainder of $6$ when divided by $(x - 1)$. Find $a$ and $b$.`, model: J(['Let $f(x) = 2x^3 + ax^2 + bx - 2$.', `Factor $(x + 2)$: ${ws401.md[0]}.`, `Remainder $6$ on division by $(x - 1)$: ${ws401.md[1]}.`, `Adding the two equations: ${ws401.md[2]}, so ${ws401.md[3]} and ${ws401.md[4]}.`]), sol: 'Turn the factor into f(−2) = 0 and the remainder into f(1) = 6, then solve the two linear equations simultaneously.', scheme: [['2a − b = 9 from f(−2) = 0', 1], ['a + b = 6 from f(1) = 6', 1], ['Solving simultaneously', 1], ['a = 5, b = 1', 1]], d: 3, c: 'application', t: [1, 2], time: 300 }), (C) => { ws401.verify(C); tplLine(['a', 'b'], ts401, r`2x^3 + ax^2 + bx - 2`).verify(C); C.assert(ab401.a.eq(5) && ab401.b.eq(1), 'a = 5, b = 1'); C.model([9, 6, 5, 1]); });
const fs402 = P(3, -4, -17, 6), fw402 = factorWork(fs402, { trials: [1, -1, 2, -2] });
Q('s402', mk.short({ marks: 4, stem: r`Find a factor of $3x^3 - 4x^2 - 17x + 6$ by trying small integer values of $x$, and hence express the polynomial as a product of three linear factors.`, model: J([`Let $f(x) = ${fs402.tex()}$. Trying divisors of $6$:`, ...fw402.trialLines.map((l) => `$${l}$`), `So $${btex(fw402.dv)}$ is a factor. Dividing:`, `$${fw402.idLine}$`, `$${fw402.qLine}$`]), sol: 'Try values that divide the constant term until one gives zero, divide by the matching factor and split the middle term of the quotient.', scheme: [['Trial values shown', 1], ['f(−2) = 0, so (x + 2) is a factor', 1], ['Quotient 3x² − 10x + 3', 1], ['(x + 2)(3x − 1)(x − 3)', 1]], d: 3, c: 'application', t: [3], time: 300 }), (C) => { fw402.w.verify(C); C.assert(fw402.z.eq(-2) && fw402.full === '(x + 2)(3x - 1)(x - 3)', `full ${fw402.full}`); C.model([-12, 16, -20, 0, fw402.full]); });
const ts403 = (e) => P(1, e.p, e.q, 5);
const pq403 = solveUnknowns(['p', 'q'], ts403, [{ at: 1, value: 5 }, { at: -2, value: 11 }]);
const ws403 = W(kctx(['p', 'q'], ts403, pq403), [r`f(1) = 1 + p + q + 5 = 5 \Rightarrow p + q = -1`, r`f(-2) = -8 + 4p - 2q + 5 = 11 \Rightarrow 2p - q = 7`, r`3p = 6`, r`p = 2`, r`q = -3`]);
Q('s403', mk.short({ marks: 4, stem: r`When $x^3 + px^2 + qx + 5$ is divided by $(x - 1)$ the remainder is $5$, and when it is divided by $(x + 2)$ the remainder is $11$. Find $p$ and $q$.`, model: J(['Let $f(x) = x^3 + px^2 + qx + 5$.', `${ws403.md[0]}.`, `${ws403.md[1]}.`, `Adding: ${ws403.md[2]}, so ${ws403.md[3]} and ${ws403.md[4]}.`, r`The polynomial is $x^3 + 2x^2 - 3x + 5$.`]), sol: 'Each remainder gives one linear equation in p and q; solve them together and check.', scheme: [['p + q = −1', 1], ['2p − q = 7', 1], ['Solving', 1], ['p = 2, q = −3', 1]], d: 3, c: 'application', t: [1], time: 300 }), (C) => { ws403.verify(C); tplLine(['p', 'q'], ts403, r`x^3 + px^2 + qx + 5`).verify(C); C.assert(ts403(pq403).tex() === 'x^3 + 2x^2 - 3x + 5', 'polynomial'); C.model([1, 7, 2, 3]); });
const fs404 = P(3, 2, -3, -2), rs404 = rem(fs404, lin(3, 2));
const ws404 = W(xctx(fs404, { zeros: [-1, F(-2, 3), 1], refs: [fs404] }), [rs404.ev.tex, r`3x^3 + 2x^2 - 3x - 2 = x^2(3x + 2) - (3x + 2) = (3x + 2)(x^2 - 1) = (3x + 2)(x - 1)(x + 1)`]);
Q('s404', mk.short({ marks: 4, stem: r`Show that $(3x + 2)$ is a factor of $3x^3 + 2x^2 - 3x - 2$. Hence factorise the polynomial completely.`, model: J([`Let $f(x) = ${fs404.tex()}$; $3x + 2 = 0$ gives $x = -\\dfrac{2}{3}$.`, `${ws404.md[0]}, so $(3x + 2)$ is a factor.`, 'Grouping the terms:', ws404.md[1]]), sol: 'Substitute minus two thirds to show the value is zero, then group the terms to take out the common bracket.', scheme: [['x = −2/3', 1], ['f(−2/3) = 0', 1], ['(3x + 2)(x² − 1)', 1], ['(3x + 2)(x − 1)(x + 1)', 1]], d: 3, c: 'application', t: [2, 3], time: 300 }), (C) => { ws404.verify(C); C.assert(rs404.value.isZero() && factorise(fs404).factors.length === 3, 'three factors'); C.model([r`-\dfrac{2}{3}`, r`(3x + 2)(x - 1)(x + 1)`]); });
const ts405 = (e) => P(2, e.m, -11, -6);
const ms405 = solveUnknowns(['m'], ts405, [{ at: -3, value: 0 }]);
const fs405 = ts405(ms405), qs405 = fs405.divBy(lin(1, 3)).q;
const ws405 = W(kctx(['m'], ts405, ms405), [r`f(-3) = 2 \times (-3)^3 + m \times (-3)^2 - 11 \times (-3) - 6 = -54 + 9m + 33 - 6 = 9m - 27`, r`9m - 27 = 0`, r`m = 3`]);
const xs405 = W(xctx(fs405, { zeros: rationalZeros(fs405), refs: [fs405, qs405] }), [`${fs405.tex()} = (x + 3)(${qs405.tex()}) = (x + 3)(2x + 1)(x - 2)`]);
Q('s405', mk.short({ marks: 4, stem: r`Find the value of $m$ for which $(x + 3)$ is a factor of $2x^3 + mx^2 - 11x - 6$. For this value of $m$, factorise the polynomial completely.`, model: J([r`Let $f(x) = 2x^3 + mx^2 - 11x - 6$. By the factor theorem, $f(-3) = 0$:`, ws405.md[0], `${ws405.md[1]}, so ${ws405.md[2]}.`, 'Dividing by $(x + 3)$ and factorising the quotient:', xs405.md[0]]), sol: 'Set the value at minus three equal to zero to find m, divide by x + 3 and split the middle term of the quotient.', scheme: [['f(−3) = 9m − 27', 1], ['m = 3', 1], ['Quotient 2x² − 3x − 2', 1], ['(x + 3)(2x + 1)(x − 2)', 1]], d: 3, c: 'application', t: [2, 3], time: 300 }), (C) => { ws405.verify(C); xs405.verify(C); tplLine(['m'], ts405, r`2x^3 + mx^2 - 11x - 6`).verify(C); C.assert(ms405.m.eq(3) && qs405.tex() === '2x^2 - 3x - 2', 'm = 3'); C.model([27, 3, r`(x + 3)(2x + 1)(x - 2)`]); });
const fs406 = P(2, -5, 4, 3), ds406 = divLines(fs406, lin(1, -2)), rs406 = rem(fs406, lin(1, -2));
const is406 = W(xctx(fs406, { refs: [fs406] }), [`${fs406.tex()} = (x - 2)(${ds406.q.tex()}) + ${ds406.r.tex()}`]);
Q('s406', mk.short({ marks: 4, stem: r`Divide $2x^3 - 5x^2 + 4x + 3$ by $(x - 2)$ using long division. Write the quotient and the remainder, and check the remainder with the remainder theorem.`, model: J([`Let $f(x) = ${fs406.tex()}$. Long division by $(x - 2)$, step by step:`, ...ds406.w.md, `Quotient $${ds406.q.tex()}$, remainder $${ds406.r.tex()}$, so ${is406.md[0]}.`, `Check: $${rs406.ev.tex}$, the same remainder.`]), sol: 'Divide the leading terms, multiply back, subtract and repeat until the remainder is a constant; then evaluate at x = 2.', scheme: [['First two quotient terms', 1], ['Quotient 2x² − x + 2', 1], ['Remainder 7', 1], ['f(2) = 7 checks it', 1]], d: 3, c: 'application', t: [1], time: 300 }), (C) => { ds406.w.verify(C); is406.verify(C); W(xctx(fs406), [rs406.ev.tex]).verify(C); C.assert(ds406.q.tex() === '2x^2 - x + 2' && ds406.r.co(0).eq(7) && rs406.value.eq(7), 'quotient and remainder'); C.model([7]); });

// =============================================================== long, 10 marks (3 + 3 + 4)
const fl01 = P(1, 2, -5, 7), rl01 = rem(fl01, lin(1, -3));
const gl01 = P(2, -1, -2, 1), rl01b = rem(gl01, lin(1, 1), 'g'), ql01 = gl01.divBy(lin(1, 1)).q;
const wl01 = W({ ...xctx(gl01, { name: 'g', zeros: rationalZeros(gl01), refs: [gl01, ql01] }) }, [rl01b.ev.tex, `${gl01.tex()} = (x + 1)(${ql01.tex()})`, `${ql01.tex()} = (2x - 1)(x - 1)`, `${gl01.tex()} = (x + 1)(2x - 1)(x - 1)`]);
Q('l01', mk.long({ marks: 10, stem: `Answer each part. Show all working.\n(a) Find the remainder when $${fl01.tex()}$ is divided by $(x - 3)$.\n(b) Show that $(x + 1)$ is a factor of $${gl01.tex()}$.\n(c) Hence factorise $${gl01.tex()}$ completely.`, model: J([`**(a)** Let $f(x) = ${fl01.tex()}$. By the remainder theorem the remainder is $f(3)$:`, `$${rl01.ev.tex}$. The remainder is $37$.`, `**(b)** Let $g(x) = ${gl01.tex()}$.`, `${wl01.md[0]}, so $(x + 1)$ is a factor by the factor theorem.`, `**(c)** Dividing by $(x + 1)$: ${wl01.md[1]}.`, `Splitting the middle term, ${wl01.md[2]}.`, `So ${wl01.md[3]}.`]), sol: 'Part (a) evaluates at x = 3; part (b) shows the value at x = −1 is zero; part (c) divides by x + 1 and factorises the quadratic quotient.', scheme: [['(a) f(3) substituted', 2], ['(a) remainder 37', 1], ['(b) g(−1) worked out', 2], ['(b) g(−1) = 0, so a factor', 1], ['(c) quotient 2x² − 3x + 1', 2], ['(c) (x + 1)(2x − 1)(x − 1)', 2]], d: 2, c: 'application', t: [1, 2, 3], time: 600 }), (C) => { W(xctx(fl01), [rl01.ev.tex]).verify(C); wl01.verify(C); C.assert(rl01.value.eq(37) && rl01b.value.isZero(), '37 and factor'); C.model([37, 0, r`(x + 1)(2x - 1)(x - 1)`]); });
const fl02 = P(4, 4, -1, 2), rl02 = rem(fl02, lin(2, 3));
const tl02 = (e) => P(1, e.k, -10, -24);
const kl02 = solveUnknowns(['k'], tl02, [{ at: -2, value: 0 }]);
const gl02 = tl02(kl02), ql02 = gl02.divBy(lin(1, 2)).q;
const wl02k = W(kctx(['k'], { g: tl02 }, kl02), [r`g(-2) = (-2)^3 + k \times (-2)^2 - 10 \times (-2) - 24 = -8 + 4k + 20 - 24 = 4k - 12`, r`4k - 12 = 0`, r`k = 3`]);
const wl02x = W(xctx(gl02, { name: 'g', zeros: rationalZeros(gl02), refs: [gl02, ql02] }), [`${gl02.tex()} = (x + 2)(${ql02.tex()})`, `${ql02.tex()} = (x + 4)(x - 3)`, `${gl02.tex()} = (x + 2)(x + 4)(x - 3)`]);
Q('l02', mk.long({ marks: 10, stem: `Answer each part. Show all working.\n(a) Find the remainder when $${fl02.tex()}$ is divided by $(2x + 3)$.\n(b) $(x + 2)$ is a factor of $g(x) = x^3 + kx^2 - 10x - 24$. Find $k$.\n(c) For this value of $k$, factorise $g(x)$ completely.`, model: J([r`**(a)** $2x + 3 = 0$ gives $x = -\dfrac{3}{2}$.`, `$${rl02.ev.tex}$. The remainder is $-1$.`, `**(b)** By the factor theorem $g(-2) = 0$: ${wl02k.md[0]}.`, `${wl02k.md[1]}, so ${wl02k.md[2]}.`, `**(c)** With $k = 3$, dividing by $(x + 2)$: ${wl02x.md[0]}.`, `${wl02x.md[1]}, so ${wl02x.md[2]}.`]), sol: 'Part (a) uses the zero of 2x + 3; part (b) sets g(−2) = 0; part (c) divides by x + 2 and factorises the quotient.', scheme: [['(a) x = −3/2 substituted', 2], ['(a) remainder −1', 1], ['(b) g(−2) = 4k − 12', 2], ['(b) k = 3', 1], ['(c) quotient x² + x − 12', 2], ['(c) (x + 2)(x + 4)(x − 3)', 2]], d: 3, c: 'application', t: [1, 2, 3], time: 600 }), (C) => { W(xctx(fl02), [rl02.ev.tex]).verify(C); wl02k.verify(C); wl02x.verify(C); tplLine(['k'], tl02, r`x^3 + kx^2 - 10x - 24`, 'g').verify(C); C.assert(rl02.value.eq(-1) && kl02.k.eq(3), 'remainder -1, k = 3'); C.model([-1, 3, 12, r`(x + 2)(x + 4)(x - 3)`]); });
const fl03 = P(1, -6, 2, -4), rl03 = rem(fl03, lin(-2, 1));
const tl03 = (e) => P(1, e.a, e.b, -15);
const abl03 = solveUnknowns(['a', 'b'], tl03, [{ at: 3, value: 0 }, { at: 1, value: -24 }]);
const gl03 = tl03(abl03), fwl03 = factorWork(gl03, { name: 'g', trials: [3] });
const wl03 = W(kctx(['a', 'b'], { g: tl03 }, abl03), [r`g(3) = 27 + 9a + 3b - 15 = 0 \Rightarrow 3a + b = -4`, r`g(1) = 1 + a + b - 15 = -24 \Rightarrow a + b = -10`, r`2a = 6`, r`a = 3`, r`b = -13`]);
Q('l03', mk.long({ marks: 10, stem: `Answer each part. Show all working.\n(a) Find the remainder when $${fl03.tex()}$ is divided by $(1 - 2x)$.\n(b) $g(x) = x^3 + ax^2 + bx - 15$ has $(x - 3)$ as a factor and leaves a remainder of $-24$ when divided by $(x - 1)$. Find $a$ and $b$.\n(c) Factorise $g(x)$ completely.`, model: J([r`**(a)** $1 - 2x = 0$ gives $x = \dfrac{1}{2}$.`, `$${rl03.ev.tex}$. The remainder is $-\\dfrac{35}{8}$.`, `**(b)** ${wl03.md[0]}.`, `${wl03.md[1]}.`, `Subtracting: ${wl03.md[2]}, so ${wl03.md[3]} and ${wl03.md[4]}.`, `**(c)** $g(x) = ${gl03.tex()}$, and $(x - 3)$ is a factor. Dividing:`, `$${fwl03.idLine}$`, `$${fwl03.qLine}$`]), sol: 'Part (a) uses the zero of 1 − 2x, which is one half; part (b) forms two linear equations from g(3) = 0 and g(1) = −24; part (c) divides by x − 3.', scheme: [['(a) x = 1/2 substituted', 2], ['(a) remainder −35/8', 1], ['(b) 3a + b = −4', 1], ['(b) a + b = −10', 1], ['(b) a = 3, b = −13', 2], ['(c) quotient x² + 6x + 5', 1], ['(c) (x − 3)(x + 1)(x + 5)', 2]], d: 4, c: 'analysis', t: [1, 2, 3], time: 720 }), (C) => { W(xctx(fl03), [rl03.ev.tex]).verify(C); wl03.verify(C); fwl03.w.verify(C); tplLine(['a', 'b'], tl03, r`x^3 + ax^2 + bx - 15`, 'g').verify(C); C.assert(rl03.value.eq(F(-35, 8)) && abl03.a.eq(3) && abl03.b.eq(-13) && fwl03.full === '(x - 3)(x + 5)(x + 1)', `values ${fwl03.full}`); C.model([r`-\dfrac{35}{8}`, 3, 13, fwl03.full]); });
const fl04 = P(3, 1, -2, 4), dl04 = divLines(fl04, lin(1, 1)), rl04 = rem(fl04, lin(1, 1)), rl04b = rem(fl04, lin(1, -2));
const hl04 = fl04.sub(P(rl04b.value)), ql04 = hl04.divBy(lin(1, -2)).q;
const wl04 = W(xctx(fl04, { refs: [fl04] }), [`${fl04.tex()} = (x + 1)(${dl04.q.tex()}) + ${dl04.r.tex()}`]);
const wl04c = W(xctx(hl04, { zeros: [2], refs: [hl04, ql04] }), [`${fl04.tex()} - ${rl04b.value.tex()} = ${hl04.tex()}`, `${hl04.tex()} = (x - 2)(${ql04.tex()})`]);
Q('l04', mk.long({ marks: 10, stem: `Let $f(x) = ${fl04.tex()}$. Show all working.\n(a) Using long division, find the quotient and the remainder when $f(x)$ is divided by $(x + 1)$.\n(b) Check your remainder with the remainder theorem, and state the number that must be subtracted from $f(x)$ so that the result is exactly divisible by $(x + 1)$.\n(c) Find the number that must be subtracted from $f(x)$ so that the result is exactly divisible by $(x - 2)$, and write the result as $(x - 2)$ times a quadratic.`, model: J(['**(a)** Long division, step by step:', ...dl04.w.md, `Quotient $${dl04.q.tex()}$, remainder $${dl04.r.tex()}$: ${wl04.md[0]}.`, `**(b)** $${rl04.ev.tex}$, the same remainder. Subtracting $4$ leaves $(x + 1)(3x^2 - 2x)$, so the number is $4$.`, `**(c)** $${rl04b.ev.tex}$. Subtracting $28$ makes the remainder $0$:`, `${wl04c.md[0]}, and ${wl04c.md[1]}.`, `(The quadratic $${ql04.tex()}$ has no linear factors, since $7^2 - 4 \\times 3 \\times 12 = -95 < 0$.)`]), sol: 'Part (a) divides term by term; part (b) evaluates at x = −1, and the remainder is what must be removed; part (c) evaluates at x = 2 and divides the new polynomial by x − 2.', scheme: [['(a) quotient 3x² − 2x', 2], ['(a) remainder 4', 1], ['(b) f(−1) = 4 checks', 2], ['(b) subtract 4', 1], ['(c) f(2) = 28, subtract 28', 2], ['(c) (x − 2)(3x² + 7x + 12)', 2]], d: 3, c: 'analysis', t: [1, 2], time: 720 }), (C) => { dl04.w.verify(C); wl04.verify(C); wl04c.verify(C); W(xctx(fl04), [rl04.ev.tex, rl04b.ev.tex]).verify(C); W(ARITH, [r`7^2 - 4 \times 3 \times 12 = -95`]).verify(C); C.assert(dl04.q.tex() === '3x^2 - 2x' && dl04.r.co(0).eq(4) && rl04.value.eq(4) && rl04b.value.eq(28) && disc(ql04).sign() < 0, 'values'); C.model([4, 28, r`3x^2 + 7x + 12`]); });
const tl05 = (e) => P(2, e.k, -8, 3);
const kl05 = solveUnknowns(['k'], tl05, [{ at: 1, value: 0 }]);
const fl05 = tl05(kl05), ql05 = fl05.divBy(lin(1, -1)).q;
const wl05k = W(kctx(['k'], tl05, kl05), [r`f(1) = 2 + k - 8 + 3 = k - 3`, r`k - 3 = 0`, r`k = 3`]);
const wl05b = W(xctx(fl05, { zeros: rationalZeros(fl05), refs: [fl05, ql05] }), [`${fl05.tex()} = (x - 1)(${ql05.tex()})`, `${ql05.tex()} = (2x - 1)(x + 3)`, `${fl05.tex()} = (x - 1)(2x - 1)(x + 3)`]);
const gl05 = P(1, -7, 7, 15), fwl05 = factorWork(gl05, { name: 'g' });
Q('l05', mk.long({ marks: 10, stem: `Answer each part. Show all working.\n(a) Find $k$ if $(x - 1)$ is a factor of $f(x) = 2x^3 + kx^2 - 8x + 3$.\n(b) For this value of $k$, factorise $f(x)$ completely.\n(c) Using the factor theorem, factorise $g(x) = ${gl05.tex()}$ completely.`, model: J([`**(a)** ${wl05k.md[0]}, and $f(1) = 0$ since $(x - 1)$ is a factor: ${wl05k.md[1]}, so ${wl05k.md[2]}.`, `**(b)** $f(x) = ${fl05.tex()}$. Dividing by $(x - 1)$: ${wl05b.md[0]}.`, `${wl05b.md[1]}, so ${wl05b.md[2]}.`, '**(c)** Try divisors of $15$:', ...fwl05.trialLines.map((l) => `$${l}$`), `So $${btex(fwl05.dv)}$ is a factor, and $${fwl05.idLine}$.`]), sol: 'Part (a) uses f(1) = 0; part (b) divides by x − 1; part (c) finds a zero by trial among the divisors of 15, then divides and factorises the quotient.', scheme: [['(a) f(1) = k − 3', 2], ['(a) k = 3', 1], ['(b) quotient 2x² + 5x − 3', 2], ['(b) (x − 1)(2x − 1)(x + 3)', 1], ['(c) g(−1) = 0 found by trial', 2], ['(c) (x + 1)(x − 3)(x − 5)', 2]], d: 3, c: 'application', t: [2, 3], time: 660 }), (C) => { wl05k.verify(C); wl05b.verify(C); fwl05.w.verify(C); tplLine(['k'], tl05, r`2x^3 + kx^2 - 8x + 3`).verify(C); C.assert(kl05.k.eq(3) && fwl05.z.eq(-1) && fwl05.full === '(x + 1)(x - 3)(x - 5)', `full ${fwl05.full}`); C.model([3, r`(x - 1)(2x - 1)(x + 3)`, fwl05.full]); });
const fl06 = P(1, -2, 5, -10), rl06 = rem(fl06, lin(1, -2));
const tl06 = (e) => P(1, e.m, e.n, -10);
const mnl06 = solveUnknowns(['m', 'n'], tl06, [{ at: 2, value: 0 }, { at: -1, value: 0 }]);
const gl06 = tl06(mnl06);
const wl06a = W(xctx(fl06, { zeros: [2], refs: [fl06] }), [rl06.ev.tex, r`x^3 - 2x^2 + 5x - 10 = x^2(x - 2) + 5(x - 2) = (x - 2)(x^2 + 5)`]);
const wl06c = W(kctx(['m', 'n'], { g: tl06 }, mnl06), [r`g(2) = 8 + 4m + 2n - 10 = 0 \Rightarrow 2m + n = 1`, r`g(-1) = -1 + m - n - 10 = 0 \Rightarrow m - n = 11`, r`3m = 12`, r`m = 4`, r`n = -7`]);
const wl06x = W(IDX, [r`x^2 - x - 2 = (x - 2)(x + 1)`]);
const wl06g = W(xctx(gl06, { name: 'g', zeros: rationalZeros(gl06), refs: [gl06] }), [r`x^3 + 4x^2 - 7x - 10 = (x^2 - x - 2)(x + 5) = (x - 2)(x + 1)(x + 5)`]);
Q('l06', mk.long({ marks: 10, stem: `Answer each part. Show all working.\n(a) Show that $(x - 2)$ is a factor of $f(x) = ${fl06.tex()}$.\n(b) Show that $f(x)$ has no other linear factor.\n(c) $g(x) = x^3 + mx^2 + nx - 10$ is exactly divisible by $x^2 - x - 2$. Find $m$ and $n$, and the third factor of $g(x)$.`, model: J([`**(a)** ${wl06a.md[0]}, so $(x - 2)$ is a factor.`, `**(b)** Grouping: ${wl06a.md[1]}.`, r`For every real $x$, $x^2 + 5 \ge 5$, so $x^2 + 5$ is never zero and has no linear factor. Hence $(x - 2)$ is the only linear factor of $f(x)$.`, `**(c)** ${wl06x.md[0]}, so $(x - 2)$ and $(x + 1)$ are both factors of $g(x)$:`, `${wl06c.md[0]}.`, `${wl06c.md[1]}.`, `Adding: ${wl06c.md[2]}, so ${wl06c.md[3]} and ${wl06c.md[4]}.`, `Then ${wl06g.md[0]}: the third factor is $(x + 5)$.`]), sol: 'Part (a) shows f(2) = 0; part (b) groups the terms and shows the quadratic factor is always positive; part (c) factorises the divisor and uses the factor theorem twice.', scheme: [['(a) f(2) = 0, so a factor', 3], ['(b) f(x) = (x − 2)(x² + 5)', 2], ['(b) x² + 5 > 0, no other linear factor', 1], ['(c) x² − x − 2 = (x − 2)(x + 1) and two equations', 2], ['(c) m = 4, n = −7, third factor (x + 5)', 2]], d: 4, c: 'analysis', t: [2, 3], time: 720 }), (C) => { wl06a.verify(C); wl06c.verify(C); wl06x.verify(C); wl06g.verify(C); tplLine(['m', 'n'], tl06, r`x^3 + mx^2 + nx - 10`, 'g').verify(C); const fac = factorise(fl06); C.assert(fac.factors.length === 1 && disc(fac.rest).sign() < 0, 'one linear factor'); C.assert(mnl06.m.eq(4) && mnl06.n.eq(-7) && factorise(gl06).tex === '(x + 5)(x + 1)(x - 2)', 'm, n, third factor'); C.model([0, 5, 4, 7, r`(x + 5)`]); });
const fl07 = P(1, 5, 2, -8), fwl07 = factorWork(fl07, { name: 'V', trials: [1] });
const dims07 = [lin(1, -1), lin(1, 2), lin(1, 4)].map((l) => l.at(6));
const rl07 = rem(fl07, lin(1, -6), 'V');
Q('l07', mk.long({ marks: 10, stem: `An imagined carton maker designs a box whose volume, in cm³, is $V(x) = ${fl07.tex()}$ for a design number $x > 1$. Show all working.\n(a) Show that $(x - 1)$ is a factor of $V(x)$.\n(b) Factorise $V(x)$ completely, so that each factor can be the length of one edge of the box.\n(c) For $x = 6$, find the three edges and the volume of the box. Find the remainder when $V(x)$ is divided by $(x - 6)$, and explain why it equals the volume.`, model: J([`**(a)** The coefficients add up to $1 + 5 + 2 - 8 = 0$: $${fwl07.trialLines[0]}$, so $(x - 1)$ is a factor.`, `**(b)** Dividing by $(x - 1)$: $${fwl07.idLine}$.`, `$${fwl07.qLine}$. The edges are $(x - 1)$ cm, $(x + 2)$ cm and $(x + 4)$ cm.`, `**(c)** At $x = 6$ the edges are $${dims07[0].tex()}$ cm, $${dims07[1].tex()}$ cm and $${dims07[2].tex()}$ cm, so the volume is $5 \\times 8 \\times 10 = 400$ cm³.`, `By the remainder theorem the remainder on division by $(x - 6)$ is $${rl07.ev.tex}$.`, 'It equals the volume because both are the value of $V(x)$ at $x = 6$.']), sol: 'Part (a) uses the sum of the coefficients; part (b) divides by x − 1 and factorises the quotient; part (c) substitutes 6 in each factor and links the remainder theorem to the value of V.', scheme: [['(a) V(1) = 0', 2], ['(a) conclusion', 1], ['(b) quotient x² + 6x + 8', 2], ['(b) (x − 1)(x + 2)(x + 4)', 1], ['(c) edges 5, 8, 10 cm and volume 400 cm³', 2], ['(c) remainder V(6) = 400, same value', 2]], d: 3, c: 'application', t: [1, 2, 3], time: 660 }), (C) => { fwl07.w.verify(C); W(ARITH, [r`1 + 5 + 2 - 8 = 0`, r`5 \times 8 \times 10 = 400`]).verify(C); W(xctx(fl07, { name: 'V' }), [rl07.ev.tex]).verify(C); C.assert(fwl07.full === '(x - 1)(x + 4)(x + 2)' && dims07.map(String).join() === '5,8,10' && rl07.value.eq(400), `values ${fwl07.full}`); C.model([5, 8, 10, 400]); });
